/**
 * Codex app-server 相关约定（透传部分）。
 *
 * 方法集来自 remote-codex-center 已对着真实 app-server 验证过的调用；
 * 网关只透传允许列表内的方法，`initialize` / `initialized` 由网关自己完成。
 * 反向请求的回包形状抄自 remote-codex-center/components/codex/approval-card.tsx。
 */
import { z } from 'zod';

export const APP_SERVER_ALLOWED_METHODS = [
  // 线程
  'thread/start',
  'thread/resume',
  'thread/fork',
  'thread/read',
  'thread/list',
  'thread/archive',
  'thread/unarchive',
  'thread/name/set',
  'thread/metadata/update',
  'thread/compact/start',
  // 轮次
  'turn/start',
  'turn/interrupt',
  'turn/steer',
  // 目标（可选）
  'thread/goal/get',
  'thread/goal/set',
  'thread/goal/clear',
  // 其他
  'model/list',
  'skills/list',
  'collaborationMode/list',
  'review/start',
  'account/rateLimits/read',
] as const;
export type AppServerMethod = (typeof APP_SERVER_ALLOWED_METHODS)[number];

export function isAppServerMethodAllowed(method: string): method is AppServerMethod {
  return (APP_SERVER_ALLOWED_METHODS as readonly string[]).includes(method);
}

/** 网关握手自用，不允许 View 发送 */
export const APP_SERVER_GATEWAY_ONLY_METHODS = ['initialize', 'initialized'] as const;

/** app-server → 客户端的通知；`item/reasoning/*` 为前缀匹配 */
export const APP_SERVER_NOTIFICATIONS = [
  'thread/started',
  'thread/status/changed',
  'skills/changed',
  'thread/name/updated',
  'thread/archived',
  'thread/tokenUsage/updated',
  'thread/goal/updated',
  'thread/goal/cleared',
  'turn/started',
  'turn/completed',
  'turn/diff/updated',
  'turn/plan/updated',
  'item/started',
  'item/completed',
  'item/agentMessage/delta',
  'item/plan/delta',
  'item/commandExecution/outputDelta',
  'item/fileChange/patchUpdated',
  'item/mcpToolCall/progress',
  'item/reasoning/summaryPartAdded',
  'item/reasoning/summaryTextDelta',
  'item/reasoning/textDelta',
  'account/rateLimits/updated',
  'serverRequest/resolved',
] as const;
export type AppServerNotification = (typeof APP_SERVER_NOTIFICATIONS)[number];

export function isAppServerNotification(method: string): boolean {
  return (
    (APP_SERVER_NOTIFICATIONS as readonly string[]).includes(method) ||
    method.startsWith('item/reasoning/')
  );
}

/** app-server → 客户端的反向请求（需要回包） */
export const APP_SERVER_SERVER_REQUESTS = {
  commandApproval: 'item/commandExecution/requestApproval',
  fileChangeApproval: 'item/fileChange/requestApproval',
  permissionsApproval: 'item/permissions/requestApproval',
  userInput: 'item/tool/requestUserInput',
  elicitation: 'mcpServer/elicitation/request',
  /** dynamic tools（实验特性，M0 核对方法名与回包） */
  dynamicToolCall: 'item/tool/call',
  /** 网关自动应答，不到 View */
  currentTime: 'currentTime/read',
} as const;
export type AppServerServerRequestMethod =
  (typeof APP_SERVER_SERVER_REQUESTS)[keyof typeof APP_SERVER_SERVER_REQUESTS];

/** 由网关自动应答、不转发给 View 的反向请求 */
export const GATEWAY_AUTO_ANSWERED_SERVER_REQUESTS: readonly string[] = [
  APP_SERVER_SERVER_REQUESTS.currentTime,
];

// ── 反向请求回包形状 ────────────────────────────────────────────

export const ApprovalDecision = z.enum(['accept', 'acceptForSession', 'decline', 'cancel']);
export type ApprovalDecision = z.infer<typeof ApprovalDecision>;

/** item/commandExecution/requestApproval、item/fileChange/requestApproval 的回包 */
export const ApprovalResponse = z.object({ decision: ApprovalDecision });
export type ApprovalResponse = z.infer<typeof ApprovalResponse>;

/** item/permissions/requestApproval 的回包 */
export const PermissionsApprovalResponse = z.object({
  permissions: z.record(z.string(), z.unknown()),
  scope: z.enum(['turn', 'session']),
});
export type PermissionsApprovalResponse = z.infer<typeof PermissionsApprovalResponse>;

/** item/tool/requestUserInput 的回包 */
export const UserInputResponse = z.object({
  answers: z.record(z.string(), z.object({ answers: z.array(z.string()) })),
});
export type UserInputResponse = z.infer<typeof UserInputResponse>;

/** mcpServer/elicitation/request 的回包 */
export const ElicitationResponse = z.object({
  action: z.enum(['accept', 'decline', 'cancel']),
  content: z.unknown().optional(),
  _meta: z.unknown().optional(),
});
export type ElicitationResponse = z.infer<typeof ElicitationResponse>;

/** item/tool/call（dynamic tool）的回包；形状按 codex app-server v2 DynamicToolCallResponse，M0 核对 */
export const DynamicToolContentItem = z.discriminatedUnion('type', [
  z.object({ type: z.literal('inputText'), text: z.string() }),
  z.object({ type: z.literal('inputImage'), imageUrl: z.string() }),
]);
export const DynamicToolCallResponse = z.object({
  contentItems: z.array(DynamicToolContentItem),
  success: z.boolean(),
});
export type DynamicToolCallResponse = z.infer<typeof DynamicToolCallResponse>;

/** item/tool/call 的请求参数（Codex → 网关 → View） */
export const DynamicToolCallParams = z.object({
  threadId: z.string(),
  turnId: z.string(),
  callId: z.string().optional(),
  tool: z.string(),
  arguments: z.unknown(),
});
export type DynamicToolCallParams = z.infer<typeof DynamicToolCallParams>;

/** 便捷构造：把结构化结果包成 dynamic tool 回包 */
export function dynamicToolResult(value: unknown, success = true): DynamicToolCallResponse {
  return {
    success,
    contentItems: [{ type: 'inputText', text: typeof value === 'string' ? value : JSON.stringify(value) }],
  };
}

// ── 常用请求参数（View 侧构造时用，宽松校验） ─────────────────────

export const CodexUserInput = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('text'),
    text: z.string(),
    text_elements: z.array(z.unknown()).optional(),
  }),
  z.object({ type: z.literal('image'), url: z.string().min(1) }),
  z.object({ type: z.literal('localImage'), path: z.string().min(1), name: z.string().optional() }),
  z.object({ type: z.literal('audio'), url: z.string().min(1) }),
  z.object({ type: z.literal('localAudio'), path: z.string().min(1), name: z.string().optional() }),
  z.object({ type: z.literal('skill'), name: z.string().min(1), path: z.string().min(1) }),
  z.object({ type: z.literal('mention'), name: z.string().min(1), path: z.string().min(1) }),
]);
export type CodexUserInput = z.infer<typeof CodexUserInput>;

export const TurnStartParams = z
  .object({
    threadId: z.string(),
    input: z.array(CodexUserInput),
  })
  .passthrough();
export type TurnStartParams = z.infer<typeof TurnStartParams>;

/** 向当前仍在执行的轮次追加指令；expectedTurnId 用于防止把消息发到已切换的轮次。 */
export const TurnSteerParams = z
  .object({
    threadId: z.string(),
    input: z.array(CodexUserInput),
    expectedTurnId: z.string(),
  })
  .passthrough();
export type TurnSteerParams = z.infer<typeof TurnSteerParams>;
